package com.renthouse.repair;import com.renthouse.common.api.*;import jakarta.validation.*;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1")public class RepairController{private final RepairService s;public RepairController(RepairService s){this.s=s;}@PostMapping("/tenant/repairs")ApiResponse<RepairView>create(@RequestBody @Valid Create r){return ApiResponse.ok(s.create(new RepairService.Create(r.contractId(),r.category(),r.description())));}@GetMapping("/repairs")ApiResponse<PageResponse<RepairView>>list(@RequestParam(defaultValue="1")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.ok(s.list(page,size));}@PostMapping("/landlord/repairs/{id}/process")ApiResponse<RepairView>process(@PathVariable long id,@RequestBody @Valid Process r){return ApiResponse.ok(s.process(id,new RepairService.Process(r.assigneeName(),r.assigneeMobile(),r.handlingNote())));}@PostMapping("/landlord/repairs/{id}/finish")ApiResponse<RepairView>finish(@PathVariable long id,@RequestBody @Valid Note r){return ApiResponse.ok(s.finish(id,r.note()));}@PostMapping("/tenant/repairs/{id}/confirm")ApiResponse<RepairView>confirm(@PathVariable long id){return ApiResponse.ok(s.confirm(id));}public record Create(@Positive long contractId,@NotBlank String category,@NotBlank@Size(max=1000)String description){}public record Process(String assigneeName,String assigneeMobile,@NotBlank String handlingNote){}public record Note(@NotBlank String note){}}
